#!/usr/bin/env bash
set -Eeuo pipefail
rsync_owned() { local src=$1 dest=$2; local args=(-az --delete --exclude node_modules --exclude tests --exclude runtime --exclude .DS_Store --exclude '.env*' --exclude '*~'); [ "$DRY_RUN" -eq 1 ] && args+=(--dry-run); args+=(-e "$(rsync_ssh_command)"); rsync "${args[@]}" "$src/" "$PRODUCTION_SSH_USER@$PRODUCTION_SSH_HOST:$dest/"; }
deploy_owned_code() { PHASE=code; dry "would rsync owned theme and plugin only; --delete is scoped to those directories"; info 'deploying owned theme with rsync'; rsync_owned "$PROJECT_ROOT/theme/rentacar-venezia-v2" "$PRODUCTION_ROOT/wp-content/themes/rentacar-venezia-v2" || die 6 'theme rsync failed'; info 'deploying rentacar-core with rsync'; rsync_owned "$PROJECT_ROOT/plugin/rentacar-core" "$PRODUCTION_ROOT/wp-content/plugins/rentacar-core" || die 6 'rentacar-core rsync failed'; [ "$DRY_RUN" -eq 1 ] && return; info 'validating deployed PHP files'; remote_exec "test -f $(shell_quote "$PRODUCTION_ROOT/wp-content/themes/rentacar-venezia-v2/style.css") && test -f $(shell_quote "$PRODUCTION_ROOT/wp-content/plugins/rentacar-core/rentacar-core.php") && find $(shell_quote "$PRODUCTION_ROOT/wp-content/themes/rentacar-venezia-v2") $(shell_quote "$PRODUCTION_ROOT/wp-content/plugins/rentacar-core") -name '*.php' -type f -exec php -l {} \\;" || die 6 'remote code validation failed'; }
code_failure_rollback() { [ "$AUTO_ROLLBACK_CODE_FAILURE" -eq 1 ] && [ "$NO_AUTO_ROLLBACK" -ne 1 ] || die 7 'code verification failed'; warn 'verification failed; restoring owned code backup'; local d; d=$(remote_backup_dir); remote_exec "cd $(shell_quote "$PRODUCTION_ROOT") && rm -rf wp-content/themes/rentacar-venezia-v2 wp-content/plugins/rentacar-core && tar -xzf $(shell_quote "$d/rentacar-venezia-v2-before.tar.gz") && tar -xzf $(shell_quote "$d/rentacar-core-before.tar.gz")" || die 8 'automatic code rollback failed'; flush_caches; die 7 'code verification failed; owned code was restored'; }
